<student_code untrusted="true">
=== submission_04.ino ===
   1| // button toggle w/ software debounce
   2| // D2 button (pullup, LOW = pressed), D13 LED, Serial1 9600
   3| 
   4| int buttonPin = 2;
   5| int ledPin = 13;
   6| 
   7| int ledState = LOW;
   8| int buttonState = HIGH;        // debounced button
   9| int lastReading = HIGH;        // previous raw reading
  10| unsigned long lastBounce = 0;  // time of the last raw change
  11| unsigned long debounceMs = 6;
  12| 
  13| void setup() {
  14|   pinMode(buttonPin, INPUT_PULLUP);
  15|   pinMode(ledPin, OUTPUT);
  16|   digitalWrite(ledPin, ledState);
  17|   Serial1.begin(9600);
  18| }
  19| 
  20| void loop() {
  21|   int reading = digitalRead(buttonPin);
  22| 
  23|   // raw input changed -> remember when
  24|   if (reading != lastReading)
  25|     lastReading = reading;
  26|     lastBounce = millis();
  27| 
  28|   // only act after the input has been steady for debounceMs
  29|   if ((millis() - lastBounce) >= debounceMs) {
  30|     if (reading != buttonState) {
  31|       buttonState = reading;
  32| 
  33|       if (buttonState == LOW) {
  34|         ledState = !ledState;
  35|         digitalWrite(ledPin, ledState);
  36|         Serial1.println(ledState == HIGH ? "ON" : "OFF");
  37|       }
  38|     }
  39|   }
  40| }
</student_code>
